function materialiseAgreement83(value){const copy=structuredClone(value);if(isLockedIssuedStatus(copy.status))return copy;if(!preserveLegacyCover84(copy))copy.coverDesign84='calm-editorial';for(const section of copy.sections||[])section.body=agreementMerge83(section.body);for(const row of copy.scope||[])row.text=agreementMerge83(row.text,false);for(const row of copy.professionalFees||[]){row.description=agreementMerge83(row.description,false);row.trigger=agreementMerge83(row.trigger,false);}return copy;}
