function complianceProblems(){
 state.compliance=normaliseComplianceState(state.compliance);
 const c=state.compliance,client=state.client||{},problems=[];
 if(!String(client.clientName||'').trim()) problems.push('Add the client or organisation name.');
 if(!String(client.adviserName||'').trim()) problems.push('Select the licensed immigration adviser.');
 if(!String(client.adviserLicence||'').trim()) problems.push('Add the adviser IAA licence number in the adviser profile before issue.');
 if(!c.licenceType) problems.push('Confirm the adviser licence type.');
 if(c.licenceType==='Provisional'&&(!String(c.supervisorName||'').trim()||!String(c.supervisorLicence||'').trim())) problems.push('Add the provisional adviser supervisor name and licence number.');
 if(c.licenceType==='Limited'&&!String(c.limitedScope||'').trim()) problems.push('Record the matters authorised by the limited licence.');
 if(!(state.scope||[]).some(item=>item.enabled!==false&&String(item.text||'').trim())) problems.push('Add at least one tailored service to the agreed scope.');
 if(!(state.professionalFees||[]).length) problems.push('Add the professional fee schedule.');
 (state.professionalFees||[]).forEach((item,index)=>{if(!String(item.description||'').trim()||!String(item.trigger||'').trim()||placeholderValue(item.amount)) problems.push(`Complete professional fee stage ${index+1}, including an actual fixed amount and payment milestone.`)});
 (state.governmentFees||[]).forEach((item,index)=>{if(!String(item.agency||'').trim()||!String(item.application||'').trim()||placeholderValue(item.amount)) problems.push(`Confirm government/disbursement row ${index+1}, including a current amount or reasonable estimate.`)});
 if(!String(client.likelyDisbursements||'').trim()) problems.push('Record likely third-party disbursements or confirm that none are presently identified.');
 if(!String(client.conflictDisclosure||'').trim()) problems.push('Complete the conflict / benefit disclosure.');
 if(!state.feeConfirmed) problems.push('Confirm fees and disbursements have been checked.');
 if(!state.clientChecked) problems.push('Confirm client, signatory and tailored scope details have been checked.');
 if(!c.licenceConfirmed) problems.push('Confirm the adviser licence details have been checked.');
 if(!c.professionalStandardsProvided) problems.push('Confirm the current IAA Professional Standards document has been provided and explained.');
 if(!c.complaintsProcedureProvided) problems.push('Confirm the internal complaints procedure has been provided.');
 if(!c.significantMattersExplained) problems.push('Confirm the significant terms of the agreement have been explained before acceptance.');
 const required=(state.signatories||[]).filter(item=>item&&item.required!==false);
 if(!required.length) problems.push('Add at least one required signatory.');
 required.forEach((item,index)=>{if(!String(item.name||'').trim()||!isUsableEmail(item.email)) problems.push(`Complete required signatory ${index+1} with a legal name and valid email address.`)});
 const norm=value=>String(value||'').trim().toLowerCase();
 if(norm(client.clientName)&&!required.some(item=>norm(item.name)===norm(client.clientName))) problems.push('The principal client must remain a required signatory.');
 if(norm(client.partnerName)&&!required.some(item=>norm(item.name)===norm(client.partnerName))) problems.push('The partner / secondary applicant is recorded as a client in Client & matter. Current IAA guidance requires all clients, including secondary applicants, to accept the written agreement.');
 return [...new Set([...problems,...serviceCoverageProblems()])];
}
