(function(){
  const CRM_ORIGIN = window.location.origin;
  let crmContext = { agreementSetId:'', canManageTemplates:false };
  let crmInitialised = false;
  let readyHandshakeTimer = 0;
  let publicToken = '';
  let publicSignatory = null;
  const clone = value => JSON.parse(JSON.stringify(value == null ? {} : value));
  const post = (type,payload={}) => {
    if(window.parent===window) return;
    window.parent.postMessage({source:'this-agreement-studio',type,...payload},CRM_ORIGIN);
  };
  function appTypeFromCaseType(caseType=''){
    const value=String(caseType||'').toLowerCase();
    if(value.includes('smc')||value.includes('skilled migrant')) return 'smc';
    if(value.includes('active investor')||value.includes('investor')) return 'investor';
    if(value.includes('parent')) return 'parent';
    if(value.includes('partner residence')||value.includes('partnership')) return 'partnership';
    if(value.includes('accreditation')) return 'accreditation';
    if(value.includes('aewv')) return 'aewv';
    if(value.includes('student')) return 'student';
    if(value.includes('visitor')) return 'visitor';
    if(value.includes('permanent residence')) return 'permanent';
    if(value.includes('citizenship')) return 'citizenship';
    return 'other';
  }
  function fullName(person={}){ return [person.firstName,person.lastName].filter(Boolean).join(' ').trim() || person.name || ''; }
  function mapClient(client={},advisers=[],appType='other'){
    const family=Array.isArray(client.familyMembers)?client.familyMembers:[];
    const partner=family.find(member=>/partner|spouse|husband|wife/i.test(member.relationship||member.type||member.role||''));
    const primary=advisers.find(item=>item.id===client.primaryAdviserId)||{};
    const principal=fullName(client)||'Client';
    const partnerName=fullName(partner);
    return {
      clientName:principal,
      partnerName,
      clientEmail:client.email||'',
      matterRef:client.oneLawClientNumber||client.matterName||client.id||'',
      adviserId:primary.id||client.primaryAdviserId||'',
      adviserName:primary.name||'',
      adviserEmail:primary.email||'',
      adviserLicence:primary.licence||primary.license||primary.liaLicence||primary.lia_licence||'',
      preparedDate:new Date().toISOString().slice(0,10),
      expectedMonths:'To be confirmed',
      matterNote:defaultMatterDescription(appType)
    };
  }
  function applyMasterTemplate(next,library){
    const master=library&&typeof library==='object'?library.masterState:null;
    if(!master||typeof master!=='object') return next;
    const preserved={serviceProfileVersion:next.serviceProfileVersion,client:next.client,appType:next.appType,sourceMode:next.sourceMode,status:next.status,sentAt:next.sentAt,acceptedAt:next.acceptedAt,acceptedBy:next.acceptedBy,token:next.token,scope:next.scope,governmentFees:next.governmentFees,professionalFees:next.professionalFees,signatories:next.signatories,emailSubject:next.emailSubject,emailBody:next.emailBody};
    const merged={...clone(next),...clone(master),...preserved};
    merged.client={...(master.client||{}),...preserved.client};
    return merged;
  }
  function hydrateLinkedClient(next,payload={}){
    if(payload.intake) next.sourceMode='intake';
    else if(payload.client) next.sourceMode='linked';
    else next.sourceMode='standalone';
    if(!payload.client) return next;
    const existing=next.client||{};
    const mapped=mapClient(payload.client,payload.advisers||[],next.appType);
    // CRM/intake data seeds a new agreement, but once an agreement has been edited
    // the Agreement Studio values are authoritative.  In particular, do not reset
    // an adviser or recipient email back to the intake/client value when reopening.
    next.client={
      ...mapped,
      ...existing,
      clientName:existing.clientName||mapped.clientName||'',
      partnerName:existing.partnerName||mapped.partnerName||'',
      clientEmail:existing.clientEmail||mapped.clientEmail||'',
      matterRef:existing.matterRef||mapped.matterRef||'',
      adviserName:existing.adviserName||mapped.adviserName||'',
      adviserEmail:existing.adviserEmail||mapped.adviserEmail||'',
      preparedDate:existing.preparedDate||mapped.preparedDate,
      expectedMonths:existing.expectedMonths||mapped.expectedMonths,
      matterNote:existing.matterNote||mapped.matterNote||defaultMatterDescription(next.appType)
    };
    const signatories=Array.isArray(next.signatories)?next.signatories:[];
    let principal=signatories.find(item=>/principal|client/i.test(item.role||''));
    if(!principal){
      principal={id:'sg-'+Date.now(),role:'Principal client',required:true};
      signatories.unshift(principal);
    }
    // Preserve an explicitly edited signatory.  The live editor keeps the
    // principal client and principal signatory in sync from this point onward.
    principal.name=principal.name||next.client.clientName||'';
    principal.email=principal.email||next.client.clientEmail||'';
    if(next.client.partnerName){
      let partner=signatories.find(item=>/partner|second client/i.test(item.role||''));
      if(!partner){
        partner={id:'sg-'+(Date.now()+1),role:'Partner / second client',required:true};
        signatories.push(partner);
      }
      partner.name=partner.name||next.client.partnerName;
    }
    next.signatories=signatories;
    return next;
  }
  function createState(payload={}){
    const saved=payload.agreementSet?.studioState;
    if(saved&&typeof saved==='object'&&Object.keys(saved).length){
      let restored=hydrateLinkedClient(clone(saved),payload);
      const restoredStatus=payload.agreementSet?.status||restored.status||'Draft';
      if(!restored.complianceVersion&&!isLockedIssuedStatus(restoredStatus)) restored=normaliseMandatoryAgreementContent(restored);
      restored.template=normaliseTemplateSettings(restored.template||{});
      restored.compliance=normaliseComplianceState(restored.compliance);
      restored.client={conflictDisclosure:DEFAULT_CONFLICT_DISCLOSURE,likelyDisbursements:DEFAULT_DISBURSEMENTS,...(restored.client||{})};
      if(!payload.client&&payload.agreementSet?.standaloneLabel){
        restored.sourceMode='standalone';
        const assigned=(payload.advisers||[]).find(item=>String(item.id||'')===String(payload.agreementSet?.adviserId||restored.client?.adviserId||''))||{};
        restored.client=seedAdviserDetails({...restored.client,clientName:payload.agreementSet.standaloneLabel,matterRef:payload.agreementSet.standaloneLabel,clientEmail:payload.agreementSet.recipientEmail||restored.client?.clientEmail||''},assigned);
      }
      restored.status=payload.agreementSet?.status||restored.status||'Draft';
      restored.acceptedAt=payload.agreementSet?.acceptedAt||payload.agreementSet?.accepted_at||restored.acceptedAt||'';
      restored.acceptedBy=payload.agreementSet?.acceptedBy||payload.agreementSet?.accepted_by||restored.acceptedBy||'';
      restored.signatories=mergeAcceptanceDetails(restored.signatories||[],payload.agreementSet?.signatories||[]);
      return restored;
    }
    let next=defaultState();
    next.status=payload.agreementSet?.status||'Draft';
    next.appType=payload.agreementSet?.appType||appTypeFromCaseType(payload.client?.caseType||'');
    if(!APP_TYPES[next.appType]) next.appType='other';
    next.template.coverSubtitle=APP_TYPES[next.appType].title;
    applyServiceSuggestions(next,next.appType);
    next.client=mapClient(payload.client||{},payload.advisers||[],next.appType);
    next.sourceMode=payload.intake?'intake':payload.client?'linked':'standalone';
    if(!payload.client&&payload.agreementSet?.standaloneLabel){
      next.client.clientName=payload.agreementSet.standaloneLabel;
      next.client.matterRef=payload.agreementSet.standaloneLabel;
      next.client.clientEmail=payload.agreementSet.recipientEmail||'';
      const assigned=(payload.advisers||[]).find(item=>String(item.id||'')===String(payload.agreementSet?.adviserId||''))||{};
      next.client=seedAdviserDetails(next.client,assigned);
    }
    const signatories=[];
    if(next.client.clientName) signatories.push({id:'sg-'+Date.now(),name:next.client.clientName,email:next.client.clientEmail||'',role:'Principal client',required:true});
    if(next.client.partnerName) signatories.push({id:'sg-'+(Date.now()+1),name:next.client.partnerName,email:'',role:'Partner / second client',required:true});
    next.signatories=signatories.length?signatories:next.signatories;
    next.emailBody=`We have prepared your engagement agreement for ${APP_TYPES[next.appType]?.title||'your immigration matter'}. It sets out the services we will provide, the professional and government fees, the payment stages, and the terms on which we will act for you.

Please review it carefully using the secure link in this email. When you are comfortable with the content, you can confirm your acceptance and sign online.

If anything needs correcting, or you would like to discuss any part of the agreement, please reply to this email before accepting it.`;
    next=hydrateLinkedClient(applyMasterTemplate(next,payload.templateLibrary||{}),payload);
    next.template.coverSubtitle=APP_TYPES[next.appType].title;
    next=normaliseMandatoryAgreementContent(next);
    next.template=normaliseTemplateSettings(next.template||{});
    next.compliance=normaliseComplianceState(next.compliance);
    next.client={conflictDisclosure:DEFAULT_CONFLICT_DISCLOSURE,likelyDisbursements:DEFAULT_DISBURSEMENTS,...(next.client||{})};
    return next;
  }
  function currentSnapshot(){
    return {
      title:`${state.client.clientName||'Agreement'} - ${currentType().title}`,
      appType:state.appType,
      status:state.status||'Draft',
      studioState:materialiseAgreement83(state),
      templateVersion:{version:state.template?.version||'1.0'},
      recipientEmail:issueRouting().recipients[0]?.email||state.client?.clientEmail||'',
      adviserId:state.client?.adviserId||'',
      adviserEmail:state.client?.adviserEmail||'',
      signatories:clone(state.signatories||[]),
      issueRouting:{
        toEmails:issueRouting().recipients.map(item=>item.email),
        ccEmail:issueRouting().adviserEmail
      }
    };
  }
  function emitSnapshot(reason='save'){ post('THIS_AGREEMENT_SNAPSHOT',{reason,agreementSetId:crmContext.agreementSetId,snapshot:currentSnapshot()}); }
  function emitTemplate(reason='save'){
    const library={masterState:clone(state),updatedAt:new Date().toISOString()};
    const versionEvent=reason==='publish'?{versionLabel:state.template?.version||'1.0',changeNote:(document.querySelector('#changeNote')?.value||'').trim(),snapshot:clone(state)}:null;
    post('THIS_AGREEMENT_TEMPLATE_LIBRARY',{reason,library,versionEvent});
  }
  function setCrmPresentation(){
    document.body.classList.add('crm-embedded-agreement');
    const product=document.querySelector('.product'); if(product) product.textContent='Agreement Studio';
    const subtitle=document.querySelector('.subtitle'); if(subtitle) subtitle.textContent='CRM agreement authoring';
    document.title='THiS Agreement Studio';
    const saveBtn=document.querySelector('#saveBtn'); if(saveBtn) saveBtn.textContent='Save to CRM';
    const issueBtn=document.querySelector('#issueBtn'); if(issueBtn){issueBtn.textContent=state.status==='Accepted'?'Agreement accepted':'Issue agreement';issueBtn.disabled=state.status==='Accepted'}
    if(saveBtn) saveBtn.disabled=state.status==='Accepted';
    const editTextBtn=document.querySelector('#editTextBtn'); if(editTextBtn) editTextBtn.disabled=state.status==='Accepted';
    document.body.classList.toggle('accepted-lock',state.status==='Accepted');
    const notice=document.querySelector('.preview>.notice'); if(notice) notice.textContent=state.status==='Accepted'?'Signed agreement - acceptance details are shown in the authorisation section':'Review client details, fees and terms before issue';
  }
  function setPublicPresentation(){
    document.body.classList.add('public-review-mode');
    document.body.classList.remove('crm-embedded-agreement');
    const product=document.querySelector('.product'); if(product) product.textContent='Agreement';
    const subtitle=document.querySelector('.subtitle'); if(subtitle) subtitle.textContent='Turner Hopkins Immigration Specialists';
    const notice=document.querySelector('.preview>.notice'); if(notice) notice.textContent='Please review this agreement carefully before accepting it.';
    const audit=document.querySelector('.audit'); if(audit) audit.textContent='Your acceptance records the agreement version, the document accepted, your name and signature, the date and time, your email address and technical audit details.';
    document.title='Agreement | Turner Hopkins Immigration Specialists';
  }
  function initFromCrm(payload={}){
    if(THIS_AGREEMENT_CLIENT_PAGE)return;
    crmAdvisers=Array.isArray(payload.advisers)?payload.advisers.slice():[];
    const incomingId=String(payload.agreementSet?.id||'');
    if(crmInitialised&&incomingId&&crmContext.agreementSetId===incomingId&&!payload.force){
      post('THIS_AGREEMENT_INITIALISED',{agreementSetId:crmContext.agreementSetId,appType:state.appType,sourceMode:state.sourceMode});
      return;
    }
    crmContext={agreementSetId:incomingId,canManageTemplates:Boolean(payload.canManageTemplates)};
    state=createState(payload);
    crmInitialised=true;
    if(readyHandshakeTimer) window.clearInterval(readyHandshakeTimer);
    if(!crmContext.canManageTemplates) document.querySelector('#templateBtn')?.remove();
    renderAll();
    setCrmPresentation();
    window.THIS_STUDIO_LIBRARY83?.init(payload);
    post('THIS_AGREEMENT_INITIALISED',{agreementSetId:crmContext.agreementSetId,appType:state.appType,sourceMode:state.sourceMode});
  }
  async function loadPublicReview(token){
    publicToken=token;
    document.body.classList.add('public-review-mode');
    const response=await fetch(`/api/agreement?token=${encodeURIComponent(token)}`,{headers:{accept:'application/json'}});
    const payload=await response.json().catch(()=>({}));
    if(!response.ok||!payload.agreement){
      window.THIS_AGREEMENT_REVIEW?.fail(payload.error||'This agreement link is invalid or has expired. Please contact Turner Hopkins.');
      return;
    }
    const issued=payload.agreement.studioState;
    if(!issued||!issued.client||!issued.template||!Array.isArray(issued.sections)||!issued.sections.length)throw Error('This agreement could not be opened. Please contact Turner Hopkins for a new link.');
    state=clone(issued);
    state.status=payload.agreement.status||state.status;
    state.acceptedAt=payload.agreement.acceptedAt||state.acceptedAt||'';
    state.acceptedBy=payload.agreement.acceptedBy||state.acceptedBy||'';
    publicSignatory=payload.signatory||null;
    state.signatories=mergeAcceptanceDetails(state.signatories||[],publicSignatory?[publicSignatory]:[]);
    if(THIS_AGREEMENT_CLIENT_PAGE)renderPages();else renderAll();
    setPublicPresentation();
    const actions=document.querySelector('.actions');
    if(actions){
      actions.innerHTML='';
      const status=document.createElement('span'); status.className='statusline'; status.textContent=publicSignatory?.status==='Accepted'?'Accepted agreement':'Secure agreement review'; actions.appendChild(status);
      if(publicSignatory?.status!=='Accepted'){
        const button=document.createElement('button'); button.className='btn primary'; button.id='publicAcceptBtn'; button.textContent='Accept agreement'; button.onclick=()=>openSigning(); actions.appendChild(button);
      }
      {
        const print=document.createElement('button'); print.className='btn secondary'; print.textContent='Print / save PDF'; print.onclick=printAgreementDocument; actions.appendChild(print);
      }
    }
    document.querySelector('#templateBtn')?.remove();
    document.querySelector('#saveBtn')?.remove();
    document.querySelector('#exportBtn')?.remove();
    document.querySelector('#issueBtn')?.remove();
    document.querySelector('#editTextBtn')?.remove();
    const acceptButton=document.querySelector('#acceptAgreement'); if(acceptButton) acceptButton.onclick=()=>acceptPublicAgreement().catch(()=>toast('Your acceptance could not be confirmed. Please try again, or contact Turner Hopkins.'));
    if(THIS_AGREEMENT_CLIENT_PAGE){
      document.querySelectorAll('.closeSign').forEach(button=>button.onclick=()=>document.querySelector('#signModal').classList.add('hidden'));
      document.querySelector('#clearSig').onclick=clearSignature;
      const scale=()=>document.documentElement.style.setProperty('--agreement-review-scale',String(Math.min(1,Math.max(.25,(innerWidth-16)/794))));
      scale();addEventListener('resize',scale,{passive:true});
      window.THIS_AGREEMENT_REVIEW?.ready();
    }
  }
  async function acceptPublicAgreement(){
    const modern=state.complianceVersion===IAA_COMPLIANCE_VERSION; if(!document.querySelector('#checkRead')?.checked||!document.querySelector('#checkFees')?.checked||!document.querySelector('#checkDocs')?.checked||(modern&&(!document.querySelector('#checkComplaints')?.checked||!document.querySelector('#checkSignificant')?.checked))||!document.querySelector('#typedName')?.value.trim()||!sigDrawn){ toast('Complete all acceptance confirmations and the signature'); return; }
    const signatureData=document.querySelector('#sigCanvas').toDataURL('image/png');
    const response=await fetch(`/api/agreement?token=${encodeURIComponent(publicToken)}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'accept',typedName:document.querySelector('#typedName').value.trim(),signatureData,declarations:modern?{read:true,fees:true,codeOfConduct:true,professionalStandards:true,complaintsProcedure:true,significantMattersExplained:true}:{read:true,fees:true,codeOfConduct:true}})});
    const payload=await response.json().catch(()=>({}));
    if(!response.ok){ toast(payload.error||'Agreement acceptance failed'); return; }
    state.status=payload.agreementStatus||'Accepted';
    document.querySelector('#signModal')?.classList.add('hidden');
    toast('Agreement accepted');
    setTimeout(()=>location.reload(),900);
  }
  window.__THIS_AGREEMENT_INIT__=initFromCrm;
  window.addEventListener('message',event=>{
    if(THIS_AGREEMENT_CLIENT_PAGE||event.origin!==CRM_ORIGIN||event.source!==window.parent) return;
    const message=event.data||{};
    if(message.type==='THIS_AGREEMENT_INIT') initFromCrm(message.payload||{});
    if(message.type==='THIS_AGREEMENT_REQUEST_SNAPSHOT') emitSnapshot(message.reason||'request');
    if(message.type==='THIS_AGREEMENT_SAVE_CONFIRMED'){
      const confirmation=message.message||'Agreement saved to CRM';
      const status=document.querySelector('#saveStatus'); if(status) status.textContent=confirmation;
      toast(confirmation);
    }
    if(message.type==='THIS_AGREEMENT_ISSUED'){
      if(message.agreementSet){ state.status=message.agreementSet.status||'Sent'; state.sentAt=message.agreementSet.issuedAt||new Date().toISOString(); }
      document.querySelector('#issueModal')?.classList.add('hidden');
      document.body.classList.remove('agreement-issue-open');
      const sendButton=document.querySelector('#simulateSend'); if(sendButton){sendButton.disabled=false;sendButton.textContent='Send agreement';}
      renderAll();
      toast(message.message||'Agreement issued');
    }
    if(message.type==='THIS_AGREEMENT_ISSUE_FAILED'){
      const sendButton=document.querySelector('#simulateSend'); if(sendButton){sendButton.disabled=false;sendButton.textContent='Send agreement';}
      const status=document.querySelector('#saveStatus'); if(status) status.textContent='Agreement issue failed';
      toast(message.message||'Agreement issue failed. Please check the details and try again.');
    }
  });
  window.addEventListener('load',()=>{
    const token=new URLSearchParams(location.search).get('token');
    if(THIS_AGREEMENT_CLIENT_PAGE){
      if(!token){window.THIS_AGREEMENT_REVIEW?.fail('This agreement link is incomplete. Please use the full link in your email or contact Turner Hopkins.');return;}
      loadPublicReview(token).catch(error=>window.THIS_AGREEMENT_REVIEW?.fail(error.message||'The agreement could not be loaded. Please contact Turner Hopkins.'));return;
    }
    if(new URLSearchParams(location.search).has('token'))return;
    setCrmPresentation();
    if(window.parent!==window){
      const saveButton=document.querySelector('#saveBtn'); if(saveButton) saveButton.onclick=()=>{ save(); setTimeout(()=>emitSnapshot('save'),20); };
      const simulate=document.querySelector('#simulateSend'); if(simulate) simulate.onclick=()=>{ try{ const snapshot=currentSnapshot(); simulate.disabled=true; simulate.textContent='Issuing...'; post('THIS_AGREEMENT_ISSUE_REQUEST',{snapshot,emailSubject:state.emailSubject,emailBody:state.emailBody,issueRouting:snapshot.issueRouting||{}}); window.setTimeout(()=>{ if(state.status!=='Sent'&&state.status!=='Accepted'){ simulate.disabled=false; simulate.textContent='Send agreement'; } },8000); }catch(error){ console.error('Agreement issue request failed',error); simulate.disabled=false; simulate.textContent='Send agreement'; toast(error?.message||'The agreement could not be issued.'); } };
      const saveTemplate=document.querySelector('#saveTemplate'); if(saveTemplate) saveTemplate.onclick=()=>{save();emitTemplate('save');toast('Template draft sent to CRM')};
      const publishTemplateButton=document.querySelector('#publishTemplate'); if(publishTemplateButton) publishTemplateButton.onclick=()=>{publishTemplate();setTimeout(()=>emitTemplate('publish'),30)};
      const announceReady=()=>{ if(!crmInitialised) post('THIS_AGREEMENT_READY'); };
      announceReady();
      readyHandshakeTimer=window.setInterval(announceReady,750);
      window.setTimeout(()=>{ if(readyHandshakeTimer) window.clearInterval(readyHandshakeTimer); },15000);
    }
    const acceptButton=document.querySelector('#acceptAgreement'); if(acceptButton&&publicToken) acceptButton.onclick=acceptPublicAgreement;
  });
})();


// Contextual Studio help drawer.
(() => {
  const button = document.getElementById('studio-help-btn');
  const overlay = document.getElementById('studio-help-overlay');
  const drawer = document.getElementById('studio-help-drawer');
  const close = document.getElementById('studio-help-close');
  if (!button || !overlay || !drawer || !close) return;
  const setOpen = (open) => {
    overlay.classList.toggle('open', open);
    drawer.classList.toggle('open', open);
    overlay.setAttribute('aria-hidden', String(!open));
    drawer.setAttribute('aria-hidden', String(!open));
    document.body.classList.toggle('studio-help-open', open);
    if (open) close.focus(); else button.focus();
  };
  button.addEventListener('click', () => setOpen(true));
  close.addEventListener('click', () => setOpen(false));
  overlay.addEventListener('click', () => setOpen(false));
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && drawer.classList.contains('open')) setOpen(false);
  });
})();
